    # Escribe tu código aquí
    pass

exercises.solution:
def es_primo(n):
    if n < 2:
        return False
    divisor = 2
    while divisor * divisor <= n:     # basta con llegar a la raíz cuadrada
        if n % divisor == 0:
            return False              # encontrado un divisor: no es primo
        divisor += 1
    return True

