def pedir_edad():
    while True:
        texto = input("Edad: ")
        if texto == "":
            print("Error: no has escrito nada")
            continue
        for c in texto:
            if c not in "0123456789":
                print("Error: escribe solo dígitos")
                break
        else:                                  # ningún carácter malo: son todo dígitos
            edad = int(texto)
            if edad <= 120:
                print(f"Edad registrada: {edad}")
                return edad
            print("Error: la edad debe estar entre 0 y 120")

